import React, { useState, useEffect, useCallback, useRef } from 'react';
import Header from './components/Header';
import ApproachCard from './components/ApproachCard';
import SidePanel from './components/SidePanel';
import './App.css';

function App() {
  const [systemState, setSystemState] = useState({
    mode: 'AI',
    aiActive: true,
    activePhase: 'north-south',
    signalState: { north: 'red', south: 'red', east: 'red', west: 'red' },
    phaseTimer: 0,
    trafficState: {
      north: { count: 0, density: 'low', waitTime: 0, queueLength: 0, speed: 0, moving: 0 },
      south: { count: 0, density: 'low', waitTime: 0, queueLength: 0, speed: 0, moving: 0 },
      east: { count: 0, density: 'low', waitTime: 0, queueLength: 0, speed: 0, moving: 0 },
      west: { count: 0, density: 'low', waitTime: 0, queueLength: 0, speed: 0, moving: 0 }
    },
    inputHealth: {
      cameras: { north: 'ok', south: 'ok', east: 'ok', west: 'ok' },
      sensors: { north: 'ok', south: 'ok', east: 'ok', west: 'ok' }
    },
    decisionExplanation: '',
    config: {},
    timestamp: Date.now()
  });

  const [events, setEvents] = useState([]);
  const [connected, setConnected] = useState(false);
  const wsRef = useRef(null);
  const reconnectTimeoutRef = useRef(null);

  const connectWebSocket = useCallback(() => {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const wsUrl = `${protocol}//${window.location.host}`;

    const ws = new WebSocket(wsUrl);
    wsRef.current = ws;

    ws.onopen = () => {
      setConnected(true);
      console.log('Connected to traffic control server');
    };

    ws.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);

        switch (data.type) {
          case 'STATE_UPDATE':
            setSystemState(data.payload);
            break;
          case 'EVENTS_UPDATE':
            setEvents(data.payload);
            break;
          default:
            break;
        }
      } catch (error) {
        console.error('Error parsing WebSocket message:', error);
      }
    };

    ws.onclose = () => {
      setConnected(false);
      console.log('Disconnected from server');
      // Reconnect after 2 seconds
      reconnectTimeoutRef.current = setTimeout(connectWebSocket, 2000);
    };

    ws.onerror = (error) => {
      console.error('WebSocket error:', error);
    };
  }, []);

  useEffect(() => {
    connectWebSocket();

    return () => {
      if (wsRef.current) {
        wsRef.current.close();
      }
      if (reconnectTimeoutRef.current) {
        clearTimeout(reconnectTimeoutRef.current);
      }
    };
  }, [connectWebSocket]);

  const sendMessage = useCallback((message) => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify(message));
    }
  }, []);

  const handleModeChange = useCallback((mode) => {
    sendMessage({ type: 'SET_MODE', mode });
  }, [sendMessage]);

  const handleStartAI = useCallback(() => {
    sendMessage({ type: 'START_AI' });
  }, [sendMessage]);

  const handleStopAI = useCallback(() => {
    sendMessage({ type: 'STOP_AI' });
  }, [sendMessage]);

  const handleRequestPhase = useCallback((phase) => {
    sendMessage({ type: 'REQUEST_PHASE', phase });
  }, [sendMessage]);

  const handleManualSignal = useCallback((approach, signal, duration) => {
    sendMessage({ type: 'MANUAL_SIGNAL_REQUEST', approach, signal, duration });
  }, [sendMessage]);

  return (
    <div className="app">
      <Header
        mode={systemState.mode}
        aiActive={systemState.aiActive}
        activePhase={systemState.activePhase}
        connected={connected}
        onModeChange={handleModeChange}
        onStartAI={handleStartAI}
        onStopAI={handleStopAI}
        decisionExplanation={systemState.decisionExplanation}
      />

      <div className="main-content">
        <div className="approach-grid">
          <ApproachCard
            approach="north"
            label="North Approach"
            signal={systemState.signalState.north}
            traffic={systemState.trafficState.north}
            inputHealth={{
              camera: systemState.inputHealth.cameras.north,
              sensor: systemState.inputHealth.sensors.north
            }}
            phaseTimer={systemState.activePhase === 'north-south' ? systemState.phaseTimer : 0}
            isActivePhase={systemState.activePhase === 'north-south'}
            mode={systemState.mode}
            onManualSignal={handleManualSignal}
            onRequestPhase={handleRequestPhase}
            decisionExplanation={systemState.decisionExplanation}
          />
          <ApproachCard
            approach="south"
            label="South Approach"
            signal={systemState.signalState.south}
            traffic={systemState.trafficState.south}
            inputHealth={{
              camera: systemState.inputHealth.cameras.south,
              sensor: systemState.inputHealth.sensors.south
            }}
            phaseTimer={systemState.activePhase === 'north-south' ? systemState.phaseTimer : 0}
            isActivePhase={systemState.activePhase === 'north-south'}
            mode={systemState.mode}
            onManualSignal={handleManualSignal}
            onRequestPhase={handleRequestPhase}
            decisionExplanation={systemState.decisionExplanation}
          />
          <ApproachCard
            approach="east"
            label="East Approach"
            signal={systemState.signalState.east}
            traffic={systemState.trafficState.east}
            inputHealth={{
              camera: systemState.inputHealth.cameras.east,
              sensor: systemState.inputHealth.sensors.east
            }}
            phaseTimer={systemState.activePhase === 'east-west' ? systemState.phaseTimer : 0}
            isActivePhase={systemState.activePhase === 'east-west'}
            mode={systemState.mode}
            onManualSignal={handleManualSignal}
            onRequestPhase={handleRequestPhase}
            decisionExplanation={systemState.decisionExplanation}
          />
          <ApproachCard
            approach="west"
            label="West Approach"
            signal={systemState.signalState.west}
            traffic={systemState.trafficState.west}
            inputHealth={{
              camera: systemState.inputHealth.cameras.west,
              sensor: systemState.inputHealth.sensors.west
            }}
            phaseTimer={systemState.activePhase === 'east-west' ? systemState.phaseTimer : 0}
            isActivePhase={systemState.activePhase === 'east-west'}
            mode={systemState.mode}
            onManualSignal={handleManualSignal}
            onRequestPhase={handleRequestPhase}
            decisionExplanation={systemState.decisionExplanation}
          />
        </div>

        <SidePanel
          events={events}
          systemState={systemState}
        />
      </div>
    </div>
  );
}

export default App;
